// Pixel art of the Ornaments, ported verbatim from the "Tier emblems · prestige pass" canvas: one 1px
// cell per path segment, on a 64×76 grid whose Avatar window is the 32×32 square at (16, 22). Each layer
// is painted by an `ornament-*` utility of src/index.css, which reads the Tier colour set on the SVG.

/** One colour of an Ornament's pixel art. */
export type OrnamentLayer = { readonly className: string; readonly d: string };

type Pip = { readonly lit: readonly OrnamentLayer[]; readonly unlit: readonly OrnamentLayer[] };

type DivisionTierFull = {
  readonly frame: readonly OrnamentLayer[];
  /** The nameplate under the numeral: the key's colours, lit in the Tier's at Division I. */
  readonly neutralPlate: readonly OrnamentLayer[];
  readonly litPlate: readonly OrnamentLayer[];
  /** Lowest first: Division IV lights the first one, Division I all four. */
  readonly pips: readonly [Pip, Pip, Pip, Pip];
};

type DivisionTierChip = {
  readonly frame: readonly OrnamentLayer[];
  /** Lowest first; an unlit pip is not drawn at this size. */
  readonly litPips: readonly OrnamentLayer[];
};

